INSERT INTO v2_array_dwd_rebuild_20261123.dwd_stock_top10_floatholders_quarantine WITH version_flags AS (SELECT *,max(toUInt8(_observation_versions>1)) OVER (PARTITION BY `ts_code`,`end_date`,`ann_date`,`holder_name`) AS _key_conflict FROM (SELECT *,uniqExact(source_record_hash) OVER (PARTITION BY `ts_code`,`end_date`,`ann_date`,`holder_name`,sys_from) AS _observation_versions FROM v2_array_dwd_rebuild_20261123.dwd_stock_top10_floatholders_unresolved)) SELECT `ts_code`,`ann_date`,`end_date`,`holder_name`,`hold_amount`,`hold_ratio`,`hold_float_ratio`,`hold_change`,`holder_type`,`instrument_id`,`instrument_type`,`exchange`,`source_code`,`event_date`,CAST(NULL,'Nullable(Date32)'),`sys_from`,CAST(NULL,'Nullable(DateTime64(3))'),`source`,`source_table`,`source_batch_id`,`source_record_hash`,`source_kind`,'ambiguous_same_time_versions' FROM version_flags WHERE _key_conflict=1